import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Menambah teks pada foto hanya butuh beberapa menit. Anda mengunggah gambar, mengetik kata-kata Anda, memilih font dan warna, lalu menempatkan teks di tempatnya.</p>\n\n<p>Panduan cara ini memandu seluruh proses langkah demi langkah. Panduan ini membahas lapisan tunggal dan berlapis, pilihan font dan ukuran, garis tepi dan bayangan, serta pengaturan ekspor yang menjaga teks tetap tajam.</p>\n\n<p>Di akhir panduan, Anda akan bisa memberi keterangan pada foto, membuat meme, memberi label pada tangkapan layar, atau mendesain grafis sosial di perangkat apa pun. Simpan foto asli sampai Anda memeriksa hasilnya.</p>\n\n<h2 id=\"before-you-start\">Sebelum Memulai: Rencanakan Kata-Kata Anda</h2>\n\n<p>Tulis teks Anda sebelum membuka tool. Keterangan yang diputuskan di awal lebih pendek dan lebih jelas daripada keterangan yang dibuat sambil menatap editor.</p>\n\n<p>Jaga tetap pendek. Judul utama beberapa kata dan keterangan satu baris bekerja jauh lebih baik daripada paragraf, yang menyembunyikan foto dan membanjiri penonton.</p>\n\n<p>Tentukan juga suasananya. Font tebal cocok untuk meme atau spanduk sale, sedangkan serif ringan cocok untuk foto pernikahan atau grafis kutipan.</p>\n\n<p>Buka <a href=\"/id/tambah-teks-ke-gambar/\">Tool Tambah Teks ke Gambar</a> di browser Anda. Semuanya berjalan lokal, sehingga foto Anda tidak pernah diunggah ke server.</p>\n\n<h2 id=\"step-by-step\">Menambah Teks pada Gambar dalam Enam Langkah</h2>\n\n<p>Prosesnya sama untuk keterangan, meme, atau label. Unggah, ketik, beri gaya, tempatkan, periksa, lalu unduh.</p>\n\n<p>Luangkan waktu pada langkah penataan gaya. Font, ukuran, warna, dan garis tepi menentukan apakah teks terbaca atau hilang ke dalam foto.</p>\n\n<ol>\n<li>Unggah gambar Anda dengan menyeretnya ke area unggah, memilihnya dari perangkat, atau menempel tangkapan layar dengan Ctrl+V.</li>\n<li>Klik Tambah Teks dan ketik keterangan Anda di kotak konten teks, memakai Enter untuk baris tambahan.</li>\n<li>Pilih font, atur ukuran teks antara 2% dan 22%, lalu pilih warna yang kontras dengan foto.</li>\n<li>Tambahkan garis tepi teks atau bayangan jatuh jika latar ramai, lalu seret lapisan ke posisinya.</li>\n<li>Tambahkan lapisan lagi untuk baris tambahan, dengan memilih setiap lapisan secara terpisah untuk menatanya sendiri.</li>\n<li>Pilih format dan kualitas ekspor, lalu klik Unduh untuk menyimpan gambar berketerangan.</li>\n</ol>\n\n<p>Buka file unduhan sekali sebelum membagikannya. Pastikan teks terbaca jelas dan tidak ada yang penting dalam foto tertutup.</p>\n\n<h2 id=\"adding-your-first-layer\">Menambah Lapisan Teks Pertama Anda</h2>\n\n<p>Klik Tambah Teks untuk membuat lapisan pertama Anda. Tool menempatkan keterangan bawaan pada gambar, dan Anda menggantinya dengan kata-kata Anda sendiri di kotak konten teks.</p>\n\n<p>Ketik kata-kata persis seperti yang Anda inginkan tampil. Kesalahan ejaan pada gambar sulit terlewat, jadi baca teks dua kali sebelum melanjutkan.</p>\n\n<p>Lapisan muncul di tengah gambar secara bawaan. Seret ke posisi yang Anda inginkan, misalnya atas untuk judul utama atau bawah untuk keterangan.</p>\n\n<p>Setiap lapisan bersifat independen. Anda bisa menata satu lapisan dalam font besar dan tebal, dan lapisan lain dalam font kecil dan ringan, tanpa keduanya saling memengaruhi.</p>\n\n<h2 id=\"choosing-a-font\">Memilih Font</h2>\n\n<p>Tool menyertakan sekumpulan font bawaan, dari sans-serif tebal sampai serif klasik. Pilih yang cocok dengan suasana gambar dan pesan Anda.</p>\n\n<p>Untuk meme dan spanduk sale, gunakan sans-serif tebal. Huruf berat tetap terbaca pada ukuran kecil dan latar yang ramai, dan itulah yang dibutuhkan meme.</p>\n\n<p>Untuk kutipan dan foto pernikahan, gunakan serif atau font yang elegan. Goresan yang lebih ringan terasa formal dan tenang, dan cocok untuk pesan yang reflektif.</p>\n\n<p>Periksa font pada ukuran yang akan Anda pakai. Font dekoratif yang terlihat indah pada ukuran besar bisa menjadi tidak terbaca saat kecil.</p>\n\n<h2 id=\"setting-text-size\">Mengatur Ukuran Teks</h2>\n\n<p>Ukuran teks berjalan dari 2 persen sampai 22 persen gambar. Judul utama butuh ukuran yang lebih besar di dekat ujung atas rentang, sedangkan keterangan atau baris kredit butuh ukuran yang lebih kecil.</p>\n\n<p>Ukuran persentase menjaga teks tetap konsisten di berbagai ukuran gambar. Pengaturan yang sama terlihat tepat pada thumbnail kecil dan foto kamera besar.</p>\n\n<p>Uji ukuran pada dimensi yang akan Anda bagikan. Judul utama yang terlihat tebal pada ukuran penuh bisa kecil dalam pratinjau feed sosial, ketika gambar ditampilkan jauh lebih kecil.</p>\n\n<p>Saat Anda memiliki dua lapisan, atur ukurannya secara berbeda. Judul utama yang besar dengan keterangan yang lebih kecil menciptakan hierarki yang jelas, dan penonton tahu apa yang dibaca dulu.</p>\n\n<h2 id=\"choosing-a-colour\">Memilih Warna Teks</h2>\n\n<p>Teks putih berfungsi pada latar gelap dan teks hitam berfungsi pada latar terang, tetapi sebagian besar foto mengandung keduanya. Periksa warna terhadap area sebenarnya tempat teks akan berada.</p>\n\n<p>Letakkan teks di atas bagian foto yang paling polos. Keterangan di atas langit jernih atau dinding kosong jauh lebih mudah dibaca daripada keterangan di atas keramaian.</p>\n\n<p>Warna terang bisa berfungsi untuk judul utama yang pendek, tetapi lebih sulit dibaca dalam keterangan panjang. Cadangkan warna kuat untuk beberapa kata, dan gunakan putih atau hitam untuk sisanya.</p>\n\n<p>Jika tidak ada warna yang berfungsi, tambahkan panel latar. Kotak gelap semi-transparan di belakang teks putih membuatnya terbaca di mana pun, meskipun menutupi lebih banyak gambar.</p>\n\n<h2 id=\"outline-and-shadow\">Menambah Garis Tepi atau Bayangan Jatuh</h2>\n\n<p>Garis tepi menggambar batas di sekeliling setiap huruf. Garis tepi gelap yang tipis di sekeliling teks putih menjaganya tetap terbaca pada langit terang, dan inilah alasan meme memakainya.</p>\n\n<p>Bayangan jatuh mengangkat teks dari latar. Bayangan menambahkan tepi gelap yang lembut di belakang huruf, dan membantu huruf menonjol tanpa tampilan keras dari garis tepi.</p>\n\n<p>Gunakan salah satu, bukan keduanya dengan kekuatan penuh. Garis tepi ditambah bayangan berat membuat teks terlihat berantakan, sedangkan satu efek saja menjaganya tetap bersih.</p>\n\n<p>Untuk teks meme klasik, gunakan huruf putih dengan garis tepi gelap yang tebal. Kombinasi itu terbaca pada hampir semua latar, dan inilah alasan kombinasi itu menjadi standar.</p>\n\n<h2 id=\"moving-layers\">Memindahkan dan Memilih Lapisan</h2>\n\n<p>Seret lapisan untuk memindahkannya ke mana pun pada gambar. Tool memungkinkan Anda memilih setiap lapisan secara terpisah saat Anda memiliki beberapa lapisan, sehingga Anda bisa mengedit satu tanpa menyentuh yang lain.</p>\n\n<p>Klik lapisan yang ingin diedit sebelum mengubah font, ukuran, atau warnanya. Mengedit lapisan yang salah adalah kesalahan umum, dan mudah dihindari dengan memeriksa lapisan mana yang aktif.</p>\n\n<p>Atas dan bawah adalah posisi klasik untuk keterangan. Judul utama di atas dan punchline di bawah adalah format meme, dan format itu bekerja karena mata membaca dari atas ke bawah.</p>\n\n<p>Jaga teks jauh dari tepi. Keterangan yang menyentuh batas terlihat sesak, dan platform sering memotong tepi lagi untuk ukuran layar berbeda.</p>\n\n<h2 id=\"rotating-text\">Memutar Lapisan Teks</h2>\n\n<p>Lapisan teks bisa dimiringkan pada sudut khusus, dan ini menambah energi pada desain. Judul utama yang sedikit diagonal terasa dinamis, sedangkan teks lurus terasa tenang dan formal.</p>\n\n<p>Gunakan rotasi secukupnya. Kemiringan kecil beberapa derajat menambah karakter, sedangkan sudut yang curam membuat teks sulit dibaca dan terlihat seperti kesalahan.</p>\n\n<p>Teks diagonal bekerja dengan baik pada poster dan grafis sosial, ketika desain dimaksudkan untuk menarik perhatian. Teks diagonal bekerja buruk pada instruksi dan label, ketika kejelasan paling penting.</p>\n\n<p>Periksa teks yang diputar pada ukuran teks itu akan dilihat. Kemiringan yang terlihat bagus pada ukuran penuh bisa membuat teks kecil tidak terbaca dalam pratinjau feed.</p>\n\n<h2 id=\"multi-line-captions\">Keterangan Beberapa Baris dan Tata Letak Meme</h2>\n\n<p>Tekan Enter di dalam kotak konten teks untuk membuat baris baru dalam lapisan yang sama. Cara ini memungkinkan Anda menulis keterangan yang membentang dua atau tiga baris tanpa lapisan tambahan.</p>\n\n<p>Untuk meme, gunakan satu lapisan untuk keterangan atas dan satu lapisan untuk keterangan bawah. Lapisan terpisah memungkinkan Anda menempatkan setiap baris persis di tempatnya.</p>\n\n<p>Jaga baris tetap pendek. Keterangan yang membentang di seluruh lebar gambar sulit dibaca, sedangkan baris pendek yang berpusat pada subjek mudah diikuti.</p>\n\n<p>Pisahkan baris pada jeda alami dalam kalimat. Pemisah baris di tengah frasa terasa janggal, sedangkan pemisah di antara frasa terasa disengaja.</p>\n\n<h2 id=\"making-a-meme\">Membuat Meme dalam Hitungan Menit</h2>\n\n<p>Meme adalah foto dengan keterangan singkat dan lucu, biasanya dalam teks putih dengan garis tepi gelap yang tebal di atas dan bawah. Formatnya sederhana, dan kesederhanaan itu adalah poinnya.</p>\n\n<p>Unggah foto, tambahkan lapisan atas untuk pengaturan dan lapisan bawah untuk punchline. Jaga setiap baris hanya beberapa kata, agar lelucon cepat sampai.</p>\n\n<p>Gunakan font tebal dan besar dengan garis tepi gelap. Tampilan meme klasik tetap terbaca pada hampir semua latar, dan inilah alasan tampilan itu menjadi standar.</p>\n\n<p>Pratinjau meme pada ukuran meme itu akan dibagikan. Lelucon yang jelas pada ukuran penuh bisa tidak terbaca dalam pratinjau feed kecil, jadi periksa sebelum memposting.</p>\n\n<h2 id=\"preview-and-export\">Mempratinjau dan Mengekspor</h2>\n\n<p>Selalu pratinjau sebelum mengunduh. Periksa bahwa teks terbaca jelas, tidak ada yang penting dalam foto tertutup, dan lapisan berada di tempat yang tepat.</p>\n\n<p>Pilih JPG untuk foto berisi teks dengan pengaturan kualitas tinggi. Tepi teks bisa sedikit melembut di bawah kompresi JPG, jadi jaga kualitas tetap tinggi untuk keterangan kecil.</p>\n\n<p>Pilih PNG untuk tangkapan layar dan grafis berisi teks. PNG bersifat lossless, sehingga tepi huruf tetap tajam, dan format ini mempertahankan transparansi saat dibutuhkan.</p>\n\n<p>Ingatlah bahwa penggeser kualitas tersembunyi untuk PNG, karena PNG bersifat lossless dan tidak memiliki pengaturan kualitas untuk disesuaikan. Itu perilaku normal, bukan masalah pada tool.</p>\n\n<h2 id=\"adding-text-on-mobile\">Menambah Teks di Ponsel atau Tablet</h2>\n\n<p>Tool ini berfungsi di layar sentuh, sehingga Anda bisa memberi keterangan pada foto di ponsel yang mengambilnya. Unggah dari galeri, ketik teks, lalu seret lapisan ke tempatnya dengan jari.</p>\n\n<p>Mengetik di keyboard ponsel lebih lambat, jadi tulis keterangan Anda sebelum membuka tool. Keterangan pendek yang direncanakan lebih mudah diketik daripada keterangan yang dibuat di tempat.</p>\n\n<p>Menyeret lapisan dengan jari kurang presisi daripada dengan mouse. Gunakan area tengah, atas, dan bawah sebagai panduan, dan perbesar untuk memeriksa penempatan.</p>\n\n<p>File unduhan tersimpan di folder unduhan biasa Anda. Dari sana Anda bisa langsung membagikan gambar berketerangan ke aplikasi chat, email, atau postingan sosial.</p>\n\n<h2 id=\"troubleshooting\">Mengatasi Masalah Teks Umum</h2>\n\n<p>Jika teks tidak terbaca, warnanya mungkin cocok dengan latar. Ubah warnanya, tambahkan garis tepi, atau pindahkan lapisan ke bagian foto yang lebih polos.</p>\n\n<p>Jika Anda mengedit lapisan yang salah, klik lapisan yang Anda maksud untuk diubah dan coba lagi. Tool memilih lapisan satu per satu, jadi periksa lapisan mana yang aktif sebelum menata gaya.</p>\n\n<p>Jika lapisan tidak mau bergerak, periksa apakah Anda sudah memilihnya dulu. Lapisan harus aktif sebelum bisa diseret, dan mengkliknya sekali biasanya memilihnya.</p>\n\n<p>Jika teks terlihat buram setelah ekspor, pengaturan kualitas JPG mungkin terlalu rendah. Ekspor ulang dengan kualitas lebih tinggi, atau beralih ke PNG untuk tepi teks paling tajam.</p>\n\n<h2 id=\"quick-tips\">Tips Cepat untuk Teks yang Lebih Baik pada Gambar</h2>\n\n<p>Jaga teks tetap pendek. Beberapa kata yang dipilih dengan baik memperkuat gambar, sedangkan paragraf yang dijejalkan ke foto menyembunyikan hal yang justru ingin digambarkan.</p>\n\n<p>Gunakan satu font untuk judul utama dan satu font untuk keterangan, paling banyak. Mencampur banyak jenis huruf terlihat kacau, sedangkan pasangan yang konsisten menjaga desain tetap bersih.</p>\n\n<p>Periksa teks pada ukuran teks itu akan dilihat. Keterangan yang terlihat bagus pada ukuran penuh bisa tidak terbaca dalam pratinjau feed sosial.</p>\n\n<p>Simpan foto asli tanpa teks. Setelah teks diratakan ke dalam ekspor, teks itu tidak bisa dihapus dari file tersebut, sehingga file asli adalah satu-satunya salinan bersih Anda.</p>\n\n<p>Untuk slide dengan latar foto yang ramai, tambahkan panel gelap semi-transparan di belakang judul. Panel ini membuat judul terbaca dari jarak jauh tanpa harus menggelapkan seluruh foto.</p>\n\n<p>Gunakan ukuran judul yang konsisten di semua slide. Judul yang berubah-ubah ukurannya membuat presentasi terlihat tidak rapi dan mengganggu perhatian penonton.</p>\n\n<p>Jangan menaruh terlalu banyak kata pada satu slide. Satu judul dan tiga sampai lima poin sudah cukup, dan detailnya bisa Anda sampaikan secara lisan saat presentasi.</p>\n\n<p>Pilih font yang sama dengan font dokumen atau laporan Anda. Konsistensi font antara slide dan dokumen membuat seluruh materi presentasi terlihat seperti satu paket yang dirancang dengan baik.</p>\n\n<p>Periksa warna teks di bawah cahaya proyektor, bukan hanya di layar laptop. Proyektor sering menampilkan warna lebih pucat, sehingga teks yang terlihat jelas di laptop bisa memudar di layar proyektor.</p>\n\n<p>Simpan versi slide tanpa teks sebagai cadangan. Jika Anda perlu mengubah judul di kemudian hari, Anda bisa mulai dari gambar bersih tanpa harus memotret atau mencari foto lagi.</p>\n\n<p>Untuk presentasi daring, ingatlah bahwa peserta menonton dari layar kecil. Judul harus cukup besar untuk dibaca di jendela video kecil, bukan hanya di layar penuh.</p>\n\n<p>Latih presentasi Anda sekali dengan slide yang sudah jadi. Latihan ini mengungkap judul yang terlalu panjang atau teks yang tertutup oleh foto sebelum penonton yang sebenarnya melihatnya.</p>\n\n<h2 id=\"text-on-presentation-slides\">Menambah Teks pada Gambar Slide Presentasi</h2>\n\n<p>Foto yang dipakai sebagai latar slide sering butuh judul di atasnya. Tambahkan judul sebagai lapisan teks, memakai font besar dan tebal yang tetap terbaca dari belakang ruangan.</p>\n\n<p>Letakkan judul di atas bagian foto yang paling polos. Judul utama di atas langit jernih atau dinding kosong jauh lebih mudah dibaca daripada judul di atas keramaian.</p>\n\n<p>Gunakan garis tepi gelap atau bayangan saat latar ramai. Efek itu mengangkat huruf dari foto secukupnya untuk dibaca, tanpa menyembunyikan gambar di bawahnya.</p>\n\n<p>Ekspor gambar slide sebagai JPG dengan pengaturan kualitas tinggi. Teks perlu tetap tajam saat slide diproyeksikan, dan ekspor berkualitas rendah akan melembutkan huruf.</p>\n\n<p>Untuk aturan keterbacaan, baca <a href=\"/id/blog/teks-pada-gambar-agar-mudah-dibaca/\">Teks pada Gambar: Font, Kontras, dan Keterbacaan</a>. Untuk gambaran menyeluruh, lihat <a href=\"/id/blog/panduan-menambah-teks-pada-gambar/\">Panduan Lengkap Menambah Teks pada Gambar</a>, dan untuk menandai kepemilikan sebagai pengganti menambah keterangan, coba <a href=\"/id/tambah-watermark-gambar/\">Tool Watermark Gambar</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Bagaimana cara menambah teks pada foto di ponsel?","answer":"Buka Tool Tambah Teks ke Gambar di browser ponsel, unggah foto dari galeri, lalu ketuk Tambah Teks. Ketik keterangan Anda, pilih font dan ukuran, seret lapisan ke posisinya dengan jari, lalu unduh hasilnya."},{"question":"Bisakah saya menambah dua keterangan berbeda pada satu gambar?","answer":"Bisa. Tambahkan lapisan terpisah untuk setiap keterangan, misalnya satu di atas dan satu di bawah. Pilih setiap lapisan sendiri untuk menatanya secara berbeda, sehingga judul utama bisa besar dan tebal, sedangkan keterangan tetap lebih kecil."},{"question":"Mengapa teks saya terlihat buram setelah mengunduh gambar?","answer":"Pengaturan kualitas JPG mungkin terlalu rendah, sehingga melembutkan tepi huruf. Ekspor ulang dengan pengaturan kualitas lebih tinggi, atau beralih ke PNG, yang bersifat lossless dan menjaga tepi teks tetap tajam."},{"question":"Bagaimana cara membuat meme klasik dengan teks atas dan bawah?","answer":"Unggah foto, tambahkan satu lapisan untuk baris atas dan satu lapisan lagi untuk baris bawah, lalu gunakan font sans-serif tebal berwarna putih dengan garis tepi gelap yang tebal. Jaga setiap baris hanya beberapa kata agar lelucon cepat sampai."},{"question":"Bisakah saya memindahkan teks setelah mengetiknya?","answer":"Bisa. Pilih lapisan lalu seret ke mana pun pada gambar. Anda bisa memindahkan, mengubah ukuran, mengubah warna, dan memutar lapisan kapan pun sebelum mengunduh. Setelah gambar diekspor, teks diratakan ke dalamnya dan tidak bisa dipindahkan."},{"question":"Seberapa besar teks seharusnya untuk postingan Instagram?","answer":"Cukup besar untuk dibaca dalam pratinjau feed kecil, bukan hanya pada ukuran penuh. Judul utama butuh ukuran di dekat ujung atas rentang 2 sampai 22 persen. Uji hasilnya dengan melihat gambar ekspor pada ukuran gambar itu akan tampil di feed."}];
